INSERT INTO projects (slug,name,description,long_description,why_it_exists,type,status,stack,topics,repo_url,homepage,cover_pattern,cover_color,featured,sort_order) VALUES
('tadooer','Tadooer','A private, self-hosted task and calendar planner for one owner.','Tadooer is a private, self-hosted task and calendar planner for one owner. Tasks sit beside the calendar on one time grid in the Planner, boards group them by filters you choose, and a focus session runs on one controlling device at a time with time landing in the worklog. A Baikal CalDAV server, bundled or one you already run, is the calendar authority, and Google Calendar connects as well. There is a web app, a Linux desktop client and an Android shell that exists in source only. There is no hosted service and no sign-up.','A planner for one person should run on that person''s own server, keep the calendar honest, and show the day and the one thing being done now on one screen.',ARRAY['software','tools']::text[],'active',ARRAY['TypeScript','React','Node.js','SQLite','CalDAV']::text[],ARRAY['planner','tasks','calendar','self-hosted']::text[],'https://git.subcult.tv/subculture-collective/tadooer',NULL,'grid','#bd93f9',true,10),
('chatty-cat','Chatty Cat','A self-hosted Twitch chat client that merges up to six channels into one scrollback.','Chatty Cat rebuilds HasanAbi Chat Thing by mxmilkiib in Go and TypeScript so SUBCULT can host it. Anonymous viewing merges up to six channels, reconnects and restores public backfill, and keeps the original palettes, fonts, filters and saved slots. The original app stays up until every parity gate passes.','Viewers who follow several streams want one log with their own settings, on a server they can trust.',ARRAY['software','media','social']::text[],'active',ARRAY['Go','TypeScript','Vite']::text[],ARRAY['twitch','chat','self-hosting']::text[],'https://git.subcult.tv/subculture-collective/chatty-cat','https://chat.subcult.tv','grid','#7dff9a',true,11),
('backline','Backline','A Discord bot and dashboard for running a community: onboarding, moderation, tickets and feeds.','Backline runs a Discord server from one place: welcome and self-assigned roles, moderation with a case history, private tickets with expiring transcripts, feeds from Twitch, YouTube and RSS, and recovery snapshots. Twenty-three modules in five groups, each switched on per server. It is a release candidate in a private pilot; public installation is not open yet.','A small community needs the same tools as a large one, without stitching six bots together.',ARRAY['software','social']::text[],'incubating',ARRAY['TypeScript','Node','discord.js','PostgreSQL','React']::text[],ARRAY['discord','moderation','community']::text[],'https://git.subcult.tv/subculture-collective/backline','https://backline.subcult.tv','sigil','#8b5cf6',false,12),
('arkhiv','Arkhiv','A zine archive: original files preserved, a catalogue with a reader and downloads.','Arkhiv acquires explicitly selected document files, preserves their original bytes and serves a catalogue with local PDF reading and downloads. The first public collection is the Anarchist Zine Archive at arkhiv.subcult.tv, with 699 documents. Rights are unknown for most of them, so nothing is offered under a reuse license.','Zines were made to be copied and handed on. An archive should keep the original and say what it knows about it.',ARRAY['software','media']::text[],'active',ARRAY['Go','React','PostgreSQL','pdf.js']::text[],ARRAY['archives','zines','preservation']::text[],'https://git.subcult.tv/subculture-collective/arkhiv','https://arkhiv.subcult.tv','dots','#d8262c',true,13),
('overlaid','Overlaid','OBS overlays, a Twitch bot and an operator desk for live streams.','Overlaid is an operator desk for a stream: alerts, chat, ticker, goals, now-playing and starting, BRB and ending overlays for OBS, Twitch events fed into them, a chat bot with commands, timers and moderation, OBS scene controls, rehearsal sessions and a health page. It runs on your own machine beside OBS. It is in development with no public instance.','One person running a stream needs the overlays, the bot and the health check on one screen.',ARRAY['software','media']::text[],'incubating',ARRAY['Go','TypeScript','React','PostgreSQL','OBS WebSocket']::text[],ARRAY['streaming','obs','twitch']::text[],'https://git.subcult.tv/subculture-collective/overlaid',NULL,'waves','#ff3b4e',false,14),
('pirs','Pirs','An experimental AT Protocol personal data server with plugin hook points.','Pirs forks the Bluesky PDS distribution to make it extensible: a draft hook-point specification, a status endpoint, a smoke test that boots a throwaway server, and a planned plugin host that never receives signing keys. It is not production software and no plugin runs yet.','A personal data server should be something its operator can extend without patching the upstream.',ARRAY['software','tools']::text[],'incubating',ARRAY['TypeScript','Node','AT Protocol']::text[],ARRAY['atproto','pds','plugins']::text[],'https://git.subcult.tv/subculture-collective/pirs',NULL,'circuit','#ffb347',false,15),
('tmux-popups','tmux-popups','A tmux popup toolkit: a quick menu and bindings generated from a TSV registry.','tmux-popups adds a Prefix+Enter quick menu and direct bindings to tmux, all generated from one popups.tsv registry. Local overrides, dependency checks in the help screen, a doctor script for tmux and TPM problems, and small or full profiles. Bash only, no build step.','Popups in tmux are useful and tedious to wire by hand. A registry makes each one a row.',ARRAY['tools']::text[],'active',ARRAY['Bash','tmux']::text[],ARRAY['tmux','terminal','dotfiles']::text[],'https://git.subcult.tv/PatrickFanella/tmux-popups',NULL,'grid','#5ad1a5',false,16),
('omarchy-monitor-bar','Omarchy Multi-Monitor Bar','A separate Omarchy bar layout for each connected monitor.','Give each monitor its own bar: Full, Minimal or Hidden, with the primary monitor locked to Full. Minimal bars show a glyph and the workspace list. A settings panel validates changes and checks the plugin against the stock Omarchy bar files it is pinned to. Ten languages.','Two monitors do not need two copies of the same bar.',ARRAY['software','tools']::text[],'active',ARRAY['QML','Quickshell','Python']::text[],ARRAY['omarchy','hyprland','desktop']::text[],'https://git.subcult.tv/PatrickFanella/omarchy-monitor-bar',NULL,'grid','#4cc9f0',false,17),
('omarchy-superproductivity','Super Productivity for Omarchy','The current Super Productivity task and its timer in the Omarchy top bar.','Shows the current Super Productivity task in the Omarchy bar with a live countdown and overtime, Stop, Complete and Extend controls, a Today list, quick add with +project, @schedule and #tag, and alerts with sound when a task expires or is due to start. It talks to the desktop app over its local REST API on loopback.','The task you are on should be visible without switching windows.',ARRAY['software','tools']::text[],'active',ARRAY['QML','Quickshell','Python']::text[],ARRAY['omarchy','super-productivity','tasks']::text[],'https://git.subcult.tv/PatrickFanella/omarchy-superproductivity',NULL,'dots','#a78bfa',false,18),
('omarchy-plugin-spool','Spool','An animated cassette companion for the Omarchy desktop that follows agent activity.','Spool is a violet cassette with acid-green limbs that lives on the Omarchy desktop. Drag it, make it jump or wave, let it wander, and watch its eyes follow the pointer. A bridge reads desktop agent activity from T3 Code and Codex and plays working, waiting, failure and review animations with a badge.','A desktop agent works in the background. Spool shows what it is doing without a window.',ARRAY['software']::text[],'active',ARRAY['QML','Quickshell','Python']::text[],ARRAY['omarchy','desktop','pets']::text[],'https://git.subcult.tv/subculture-collective/omarchy-plugin-spool',NULL,'sigil','#8a5cff',false,19),
('omarchy-plugin-shelfish','Shelfish','Collapsible, named groups of Omarchy bar widgets.','Shelfish organises existing Omarchy bar widgets into named, ordered, collapsible groups with an icon and direction. A group reveals itself when a member’s watched status changes, with per-widget reveal policies, and restores every widget before removal. Ten languages, no runtime dependencies.','A bar with twelve widgets is a bar nobody reads.',ARRAY['software','tools']::text[],'active',ARRAY['QML','Quickshell']::text[],ARRAY['omarchy','desktop','bar']::text[],'https://git.subcult.tv/PatrickFanella/omarchy-plugin-shelfish',NULL,'grid','#ffb86b',false,20),
('obsidian-plugin-metronome-tuner','Metronome + Tuner','A metronome and chromatic tuner inside Obsidian.','A metronome from 30 to 300 BPM with tap tempo, time signatures, accents and seven click sounds, and a chromatic tuner that shows frequency, cents and the nearest note with an adjustable A4 reference. The microphone is used only after you opt in, and the audio is analysed locally. Desktop and mobile.','Practice notes and the practice tools belong in the same window.',ARRAY['software','tools']::text[],'active',ARRAY['TypeScript','Obsidian API','Web Audio']::text[],ARRAY['obsidian','music','practice']::text[],'https://git.subcult.tv/PatrickFanella/obsidian-plugin-metronome-tuner',NULL,'waves','#e04e7a',false,21),
('super-productivity-mcp','super-productivity-mcp','An MCP server, plugin bridge and quick-add launcher for Super Productivity.','Lets an MCP client create and list tasks and projects, add time, and manage schedules and recurrence in Super Productivity through a plugin bridge with a file-based inbox and outbox. A quick-add launcher runs through Walker or a GTK popup on Omarchy. Broad writes are dry-run first.','An assistant should be able to add the task where you actually keep your tasks.',ARRAY['tools','software']::text[],'active',ARRAY['Go','JavaScript','MCP']::text[],ARRAY['mcp','super-productivity','agents']::text[],'https://git.subcult.tv/PatrickFanella/super-productivity-mcp',NULL,'circuit','#34d399',false,22)
